import { useState, useCallback } from 'react';

interface MutationOptions<TData, TVariables> {
  mutationFn: (variables: TVariables) => Promise<TData>;
  onMutate: (variables: TVariables) => void;
  onError: (error: Error, rollback: () => void) => void;
  onSuccess?: (data: TData) => void;
}

export function useOptimisticMutation<TData, TVariables>(options: MutationOptions<TData, TVariables>) {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const mutate = useCallback(async (variables: TVariables, currentSnapshot: () => void) => {
    setIsLoading(true);
    setError(null);

    // 1. Optimistic apply
    options.onMutate(variables);

    try {
      // 2. Perform actual server mutation
      const result = await options.mutationFn(variables);
      options.onSuccess?.(result);
      return result;
    } catch (err) {
      const mutationError = err instanceof Error ? err : new Error(String(err));
      setError(mutationError);
      // 3. Rollback state to snapshot
      options.onError(mutationError, currentSnapshot);
      throw mutationError;
    } finally {
      setIsLoading(false);
    }
  }, [options]);

  return { mutate, isLoading, error };
}
