import React, { createContext, useContext, useState, useId } from 'react';

interface AccordionContextType {
  openItems: Set<string>;
  toggleItem: (id: string) => void;
}

const AccordionContext = createContext<AccordionContextType | null>(null);

export const Accordion: React.FC<{ children: React.ReactNode; allowMultiple?: boolean }> = ({
  children,
  allowMultiple = false,
}) => {
  const [openItems, setOpenItems] = useState<Set<string>>(new Set());

  const toggleItem = (id: string) => {
    setOpenItems(prev => {
      const next = new Set(allowMultiple ? prev : []);
      if (prev.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  return <AccordionContext.Provider value={{ openItems, toggleItem }}>{children}</AccordionContext.Provider>;
};

export const AccordionItem: React.FC<{ id?: string; children: React.ReactNode }> = ({ id, children }) => {
  const autoId = useId();
  const itemId = id || autoId;
  return <div className="border-b border-gray-200 py-2" data-accordion-item={itemId}>{children}</div>;
};

export const AccordionTrigger: React.FC<{ itemId: string; children: React.ReactNode }> = ({ itemId, children }) => {
  const ctx = useContext(AccordionContext);
  if (!ctx) throw new Error('AccordionTrigger must be used within an Accordion');
  const isOpen = ctx.openItems.has(itemId);

  return (
    <button
      type="button"
      onClick={() => ctx.toggleItem(itemId)}
      aria-expanded={isOpen}
      className="flex w-full items-center justify-between py-2 text-left font-medium text-gray-900 hover:text-blue-600"
    >
      {children}
      <span className="ml-2 transition-transform duration-200">{isOpen ? '▲' : '▼'}</span>
    </button>
  );
};

export const AccordionContent: React.FC<{ itemId: string; children: React.ReactNode }> = ({ itemId, children }) => {
  const ctx = useContext(AccordionContext);
  if (!ctx) throw new Error('AccordionContent must be used within an Accordion');
  if (!ctx.openItems.has(itemId)) return null;

  return <div className="pt-2 pb-4 text-sm text-gray-600">{children}</div>;
};
